layers.vertex:
attribute vec3 aO,aE;attribute float aT;uniform float uTime;varying vec3 vN,vV;
void main(){float u=uTime-aT-.1,L=length(aE-aO),tt=L/10.;if(u<0.||u>tt){gl_Position=vec4(2.,2.,2.,1.);return;}
float k=u/tt;vec3 f=normalize(aE-aO),rt=normalize(cross(f,vec3(0.,1.,0.))),up=cross(rt,f);float spin=u*1.2;
vec3 q=position;vec3 rn=normal;q.xy=mat2(cos(spin),-sin(spin),sin(spin),cos(spin))*q.xy;rn.xy=mat2(cos(spin),-sin(spin),sin(spin),cos(spin))*rn.xy;
vec3 C=mix(aO,aE,k)+vec3(0.,min(1.8,.22*L)*4.*k*(1.-k),0.);vec3 P=C+rt*q.x+up*q.y+f*q.z;
vN=rt*rn.x+up*rn.y+f*rn.z;vV=normalize(cameraPosition-P);gl_Position=projectionMatrix*viewMatrix*vec4(P,1.);}

attribute vec3 aO, aE; attribute float aT; uniform float uTime; varying float vS, vY, vF; float arcH(float L){ return min(1.8, .22*L); } vec3 arcAt(vec3 a, vec3 b, float f){ return mix(a, b, f) + vec3(0., arcH(length(b - a))*4.*f*(1. - f), 0.); }
    void main(){
      float u = uTime - aT - 0.10, L = length(aE - aO), tt = L/10.0;
      if (u < 0. || u > tt + .2){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vec3 d = (aE - aO)/L;
      float head = min(u*10.0, L), tail = max(0., head - 1.4) + max(0., u - tt)/.2*1.7;   // after the hit, the tail catches up
      if (head - tail < .01){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float s = position.x*.5 + .5;
      float fa = mix(tail, head, s)/L;
      vec3 P = arcAt(aO, aE, fa), T = normalize(arcAt(aO, aE, min(fa + .01, 1.)) - arcAt(aO, aE, max(fa - .01, 0.)));
      vec3 side = normalize(cross(T, P - cameraPosition));
      vS = s; vY = position.y; vF = 1. - clamp((u - tt)/.2, 0., 1.);
      gl_Position = projectionMatrix*viewMatrix*vec4(P + side*position.y*(.02 + .09*s), 1.);
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying float vS, vY, vF;
    void main(){ float a = pow(vS, 1.6)*exp(-vY*vY*5.), c = pow(vS, 3.)*exp(-vY*vY*30.);
      vec3 o = (mix(uOrange, uGold, .6)*a*.55 + vec3(1., .95, .85)*c*.35)*vF;
      if (max(o.r, max(o.g, o.b)) < .002) discard; gl_FragColor = vec4(o, 1.); }
